def integer(value, minimum=0):
    if type(value) is not int or value < minimum:
        raise ValueError('invalid integer')


def allocate_discount(lines, discount):
    integer(discount)
    if not isinstance(lines, list) or not lines:
        raise ValueError('lines required')
    gross = {}
    for line in lines:
        if not isinstance(line, dict): raise ValueError('line must be a dict')
        sku = line.get('sku')
        if not isinstance(sku, str) or not sku or sku in gross: raise ValueError('invalid or duplicate sku')
        qty, price = line.get('qty'), line.get('unit_price')
        integer(qty, 1); integer(price)
        gross[sku] = qty * price
    subtotal = sum(gross.values())
    if discount > subtotal: raise ValueError('discount exceeds subtotal')
    if subtotal == 0:
        if discount: raise ValueError('discount exceeds zero subtotal')
        return {sku: 0 for sku in gross}
    products = {sku: discount * value for sku, value in gross.items()}
    shares = {sku: product // subtotal for sku, product in products.items()}
    left = discount - sum(shares.values())
    for sku in sorted(gross, key=lambda s: (-(products[s] % subtotal), s))[:left]: shares[sku] += 1
    return {sku: value - shares[sku] for sku, value in gross.items()}


def refund_delta(total, qty, cancelled, delta):
    integer(total); integer(qty, 1); integer(cancelled); integer(delta, 1)
    if cancelled >= qty or cancelled + delta > qty: raise ValueError('invalid cancellation quantity')
    return total * (cancelled + delta) // qty - total * cancelled // qty

