from copy import deepcopy
import json
from .clock import parse_time
from .money import allocate_discount, refund_delta
from .inventory import reserve, release


def _canonical(value):
    if isinstance(value, dict):
        return {k: _canonical(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_canonical(v) for v in value]
    return value


def _fingerprint(event):
    canonical = _canonical(event)
    canonical['at'] = parse_time(event.get('at')).isoformat()
    if event.get('type') == 'reserve':
        canonical['expires_at'] = parse_time(event.get('expires_at')).isoformat()
    try:
        return json.dumps(canonical, sort_keys=True, separators=(',', ':'), allow_nan=False)
    except (TypeError, ValueError) as exc:
        raise ValueError('event must be JSON-compatible') from exc


class OrderBook:
    def __init__(self, initial_stock):
        if not isinstance(initial_stock, dict) or any(not isinstance(k, str) or not k or type(v) is not int or v < 0 for k, v in initial_stock.items()):
            raise ValueError('invalid initial stock')
        self.stock = deepcopy(initial_stock)
        self.orders = {}
        self.seen = {}
        self.as_of = None

    def snapshot(self):
        orders = {oid: {k: deepcopy(order[k]) for k in ('status', 'remaining', 'line_totals', 'charged', 'refunded')} for oid, order in self.orders.items()}
        return {'stock': deepcopy(self.stock), 'orders': orders, 'as_of': self.as_of.isoformat() if self.as_of is not None else None}

    def apply(self, event):
        try:
            if not isinstance(event, dict): raise ValueError('event must be a dict')
            for field in ('id', 'order_id', 'type'):
                if not isinstance(event.get(field), str) or not event[field]: raise ValueError('invalid envelope')
            if event['type'] not in ('reserve', 'confirm', 'cancel'): raise ValueError('unknown event type')
            now = parse_time(event.get('at'))
            fingerprint = _fingerprint(event)
            if event['id'] in self.seen:
                if self.seen[event['id']] != fingerprint: raise ValueError('conflicting duplicate id')
                return None
            if self.as_of is not None and now < self.as_of: raise ValueError('time went backwards')
            staged = OrderBook(self.stock)
            staged.orders = deepcopy(self.orders); staged.seen = dict(self.seen); staged.as_of = self.as_of
            staged._expire(now)
            staged._dispatch(deepcopy(event), now)
            staged.as_of = now; staged.seen[event['id']] = fingerprint
            self.__dict__ = staged.__dict__
            return None
        except ValueError:
            raise
        except (TypeError, KeyError, AttributeError, OverflowError) as exc:
            raise ValueError('invalid event') from exc

    def _expire(self, now):
        for order in self.orders.values():
            if order['status'] == 'reserved' and order['expires_at'] <= now:
                release(self.stock, order['remaining'])
                order['remaining'] = {sku: 0 for sku in order['remaining']}
                order['status'] = 'expired'

    def _dispatch(self, event, now):
        oid, kind = event['order_id'], event['type']
        if kind == 'reserve':
            if oid in self.orders: raise ValueError('order id already used')
            lines = event.get('lines')
            totals = allocate_discount(lines, event.get('discount', 0))
            expiry = parse_time(event.get('expires_at'))
            if expiry <= now: raise ValueError('expiry must be later')
            items = {line['sku']: line['qty'] for line in lines}
            reserve(self.stock, items)
            self.orders[oid] = {'status':'reserved','remaining':deepcopy(items),'line_totals':totals,'charged':0,'refunded':0,
                'original':deepcopy(items),'cancelled':{sku:0 for sku in items},'expires_at':expiry}
            return
        if oid not in self.orders: raise ValueError('unknown order')
        order = self.orders[oid]
        if kind == 'confirm':
            if order['status'] != 'reserved': raise ValueError('order is not reserved')
            order['status'] = 'confirmed'; order['charged'] = sum(order['line_totals'].values()); return
        if order['status'] not in ('reserved','confirmed'): raise ValueError('order not cancellable')
        if 'items' in event:
            items = event['items']
        else:
            items = {sku: qty for sku, qty in order['remaining'].items() if qty}
        if not isinstance(items, dict) or not items: raise ValueError('invalid cancellation')
        for sku, qty in items.items():
            if sku not in order['remaining'] or type(qty) is not int or qty <= 0 or qty > order['remaining'][sku]: raise ValueError('invalid cancellation item')
        if order['status'] == 'reserved' and sum(items.values()) != sum(order['remaining'].values()): raise ValueError('reserved order cancellation must be full')
        for sku, qty in items.items():
            if order['status'] == 'confirmed':
                order['refunded'] += refund_delta(order['line_totals'][sku], order['original'][sku], order['cancelled'][sku], qty)
            order['remaining'][sku] -= qty; order['cancelled'][sku] += qty
        release(self.stock, items)
        if all(qty == 0 for qty in order['remaining'].values()): order['status'] = 'cancelled'


def replay(initial_stock, events):
    try:
        decorated = [(parse_time(e.get('at')), i, e) for i, e in enumerate(events)]
    except (TypeError, KeyError, AttributeError, ValueError) as exc:
        raise ValueError('invalid replay events') from exc
    ordered = [e for _, _, e in sorted(decorated, key=lambda item: (item[0], item[1]))]
    book = OrderBook(initial_stock)
    for event in ordered: book.apply(event)
    return book.snapshot()

source.shop/inventory.py:
def _validate(stock, items):
    if not isinstance(stock, dict) or not isinstance(items, dict) or not items: raise ValueError('invalid inventory request')
    for sku, qty in items.items():
        if not isinstance(sku, str) or not sku or sku not in stock or type(qty) is not int or qty <= 0: raise ValueError('invalid sku or quantity')
        if type(stock[sku]) is not int or stock[sku] < 0: raise ValueError('invalid stock')


def reserve(stock, items):
    _validate(stock, items)
    if any(stock[sku] < qty for sku, qty in items.items()): raise ValueError('insufficient stock')
    for sku, qty in items.items(): stock[sku] -= qty


def release(stock, items):
    _validate(stock, items)
    for sku, qty in items.items(): stock[sku] += qty

